import{calculator,has,pos,frac,pick,nonneg,dflt}from './core.js?ver=5f66f48b97';const MODES=['dc','ac1','ac3'];
function circuit(inputs,data){const mode=pick(inputs,'mode',MODES,'ac1');const volts=mode==='dc'?pos(inputs,'volts',undefined,has(inputs,'volts')?undefined:'volts_required_dc'):pos(inputs,'volts',mode==='ac3'?dflt(data,'v_3ph'):dflt(data,'v_1ph'));const pf=mode==='dc'?1:frac(inputs,'pf',dflt(data,'pf_mixed'));const k=mode==='ac3'?Math.sqrt(3):1;return{mode,volts,pf,k};}
export const watts_to_amps=calculator((i,d)=>{const{mode,volts,pf,k}=circuit(i,d);const watts=nonneg(i,'watts');return{mode,volts,pf,k,watts,amps:watts/(k*volts*pf)};});export const amps_to_watts=calculator((i,d)=>{const{mode,volts,pf,k}=circuit(i,d);const amps=nonneg(i,'amps');const watts=k*volts*amps*pf;return{mode,volts,pf,k,amps,watts,kw:watts/1000,va:k*volts*amps};});export const kw_to_amps=calculator((i,d)=>{const{mode,volts,pf,k}=circuit(i,d);const kw=nonneg(i,'kw');return{mode,volts,pf,k,kw,amps:(kw*1000)/(k*volts*pf)};});export const amps_to_kw=calculator((i,d)=>{const direction=pick(i,'direction',['amps_to_kw','kw_to_amps'],'amps_to_kw');if(direction==='kw_to_amps'){const r=kw_to_amps.raw(i,d);return{...r,direction,watts:r.kw*1000,va:r.k*r.volts*r.amps};}
const r=amps_to_watts.raw(i,d);return{...r,direction,kw:r.watts/1000};});export const kva_to_kw=calculator((i,d)=>{const kva=nonneg(i,'kva');const pf=frac(i,'pf',dflt(d,'pf_mixed'));return{kva,pf,kw:kva*pf};});export const kw_to_kva=calculator((i,d)=>{const kw=nonneg(i,'kw');const pf=frac(i,'pf',dflt(d,'pf_mixed'));return{kw,pf,kva:kw/pf};});export const va_to_watts=calculator((i,d)=>{const va=nonneg(i,'va');const pf=frac(i,'pf',dflt(d,'pf_ups_line_interactive'));return{va,pf,watts:va*pf};});export const watts_to_va=calculator((i,d)=>{const watts=nonneg(i,'watts');const pf=frac(i,'pf',dflt(d,'pf_ups_line_interactive'));return{watts,pf,va:watts/pf};});export const ah_to_wh=calculator((i)=>{const ah=nonneg(i,'ah');const volts=pos(i,'volts');const wh=ah*volts;return{ah,volts,wh,kwh:wh/1000};});export const wh_to_ah=calculator((i)=>{const wh=nonneg(i,'wh');const volts=pos(i,'volts');return{wh,volts,ah:wh/volts};});export const kwh_to_ah=calculator((i)=>{const kwh=nonneg(i,'kwh');const volts=pos(i,'volts');return{kwh,volts,ah:(kwh*1000)/volts};});
export const units=calculator((i,d)=>{const input=pick(i,'input',['watts','amps','ah'],has(i,'amps')?'amps':has(i,'ah')?'ah':'watts');if(input==='ah'){const ah=nonneg(i,'ah');const volts=pos(i,'volts');return withCost(i,{input,ah,volts,units:(ah*volts)/1000});}
const hours=nonneg(i,'hours');const days=nonneg(i,'days',1);let watts;const out={input,hours,days};if(input==='amps'){const{mode,volts,pf,k}=circuit(i,d);const amps=nonneg(i,'amps');watts=k*volts*amps*pf;Object.assign(out,{mode,volts,pf,amps});}else{watts=nonneg(i,'watts');}
return withCost(i,{...out,watts,units:(watts*hours*days)/1000});});function withCost(i,out){if(!has(i,'tariff'))return out;const tariff=nonneg(i,'tariff');return{...out,tariff,rs:out.units*tariff};}
export const hp_to_kw=calculator((i,d)=>{const hp=nonneg(i,'hp');const motor_eff=frac(i,'motor_eff',dflt(d,'motor_eff'));const kw=(hp*dflt(d,'w_per_hp'))/1000;return{hp,kw,motor_eff,input_kw:kw/motor_eff};});
